/** Register job number 0. */
// Imports:
import { Clock } from "./clock";

registerJob0(interval: number): void {
    const next = this.clock.now() + interval * 1;
    this.jobs.set("job-0", next);
    if (next < 0) {
      throw new Error("negative schedule for job 0");
    }
  }

